<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mbomsourcing extends CI_Controller {    private $limit = 5;    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY."mbommodel");        $this->load->helper('xssclean');        $this->load->helper('common');        error_reporting(E_ALL);        fnIfCheckUserLoggedIn();    }    public function addedit() {        $ArrData												= array('ArrBasicInfo'=>array(),'VarId'=>'','VarNew'=>0);        $VarId		    									    = $this->uri->segment(4);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->mbommodel->fnBGetInfo('','',$VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {            $ArrData['VarNew']  							    = 1;        }        $this->load->view(CNFCOMPANY.'addeditbomsourcing',$ArrData);    }    public function updateInfo() {        $VarUserInfo = fnGetUserLoggedInfo(1);        $VarCompanyId = $VarUserInfo['companyid'];        $ArrResult                                              = array();        $VarSupplierAddr				    					= xssclean($this->input->post('soaddr'));        $VarSuppliername				    					= xssclean($this->input->post('sup'));        $VarEmailid				    					= xssclean($this->input->post('ema'));        $VarPhone				    					= xssclean($this->input->post('pho'));        $VarMobile				    					= xssclean($this->input->post('mob'));        $VarStatus											    = xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        if($VarSuppliername<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'type'=>'2','address'=>$VarSupplierAddr,'emailid'=>$VarEmailid,'mobile'=>$VarMobile,                'phone'=>$VarPhone,'companyid'=>$VarCompanyId,'suppliername'=>$VarSuppliername,'status'=>$VarStatus,                'updatedby'=>$VarUserInfo['id'],'dateupdated'=>date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrStatus                                          = $this->mbommodel->saveBInfo($ArrUpdateData);            echo json_encode($ArrStatus);unset($ArrStatus);unset($ArrUpdateData);die;        } else {            $ArrResult['errcode']							    = '-1';            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function managebomsrc() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarSrcDetail											= xssclean($this->input->post('bn'));        $VarUserId											    = xssclean($this->input->post('u'));        $VarSuppName											= xssclean($this->input->post('sn'));        $VarPwdExp											    = xssclean($this->input->post('ex'));        $VarStatus  											= xssclean($this->input->post('s'));        $clickedColumnId  										= xssclean($this->input->post('columnId'));        $newsortorder  										    = xssclean($this->input->post('sortorder'));        $VarAfilter  										    = xssclean($this->input->post('afilter'));        $ArrDbCols = array('b.suppliername','b.address','b.emailid','b.phone','b.mobile','b.dateupdated','b.status','u.contactname');        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mbomsourcing/managebomsrc/';            $config['total_rows']								= $this->mbommodel->fnBCount($VarSrcDetail,$VarSuppName,$VarUserId,$VarPwdExp,$VarStatus,$VarAfilter);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "dateupdated";            $sortorder											= "desc";            if($clickedColumnId <> '' && $newsortorder <> '') {                if(array_key_exists($clickedColumnId,$ArrDbCols)) {                    $sortby = $ArrDbCols[$clickedColumnId];                }                $sortorder = $newsortorder;            }            $ArrFabricTypeList								    = $this->mbommodel->fnBList($VarSrcDetail,$VarSuppName,$VarUserId,$VarPwdExp,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAfilter)->result();            $data['pagination']									= $this->pagination->create_linkswithajax('BomSrc');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrFabricTypeList as $ObjFabric){                $ArrFnlList[$i]['id']						    = $ObjFabric->id;                $ArrFnlList[$i]['addr']						    = $ObjFabric->address;                $ArrFnlList[$i]['sup']						    = $ObjFabric->suppliername;                $ArrFnlList[$i]['ub']						    = $ObjFabric->contactname;                $ArrFnlList[$i]['em']						    = $ObjFabric->emailid;                $ArrFnlList[$i]['ph']						    = $ObjFabric->phone;                $ArrFnlList[$i]['mo']						    = $ObjFabric->mobile;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjFabric->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i:s',strtotime($ObjFabric->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'managebomsrc');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->mbommodel->fnBChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }    function delInfo() {        $VarYarnId                                            = xssclean($this->input->post('id'));        $VarUpdatedBy                                           = fnGetUserLoggedInfo();        if($VarYarnId>=1) {            $ArrResult             					            = $this->mbommodel->fnBDel($VarYarnId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						        = -1;            $ArrResult['msg']							        = '';        }        echo json_encode($ArrResult);    }}